import { readFileSync } from "node:fs";

const path = process.argv[2];
const raw = JSON.parse(readFileSync(path, "utf8"));
const samples = raw.result
  .map((s) => (typeof s === "string" ? JSON.parse(s) : s))
  .sort((a, b) => a.at - b.at);

const p = (arr, q) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(q * s.length))];
};

console.log(`samples: ${samples.length}`);
console.log(`keys: ${[...new Set(samples.flatMap(Object.keys))].join(", ")}`);

// Cadence: gap between consecutive lookups, ignoring idle gaps > 60s.
const gaps = [];
for (let i = 1; i < samples.length; i++) {
  const g = samples[i].at - samples[i - 1].at;
  if (g <= 60_000) gaps.push(g);
}
console.log(
  `\ncadence  n=${gaps.length}  p50=${p(gaps, 0.5)}  p90=${p(gaps, 0.9)}  mean=${Math.round(gaps.reduce((a, b) => a + b, 0) / gaps.length)}`,
);

const ms = samples.map((s) => s.ms ?? s.durationMs).filter((n) => n != null);
console.log(`duration n=${ms.length}  p50=${p(ms, 0.5)}  p90=${p(ms, 0.9)}`);

// Distribution of MusicBrainz calls per lookup
const mb = {};
for (const s of samples) mb[s.musicBrainzCalls] = (mb[s.musicBrainzCalls] ?? 0) + 1;
console.log(`\nmusicBrainzCalls per lookup: ${JSON.stringify(mb)}`);

const st = {};
for (const s of samples) st[s.status] = (st[s.status] ?? 0) + 1;
console.log(`status: ${JSON.stringify(st)}`);

// Session boundaries (idle gaps > 60s) so we can see distinct runs
console.log("\nruns (split on >60s idle):");
let start = 0;
for (let i = 1; i <= samples.length; i++) {
  const idle =
    i === samples.length || samples[i].at - samples[i - 1].at > 60_000;
  if (!idle) continue;
  const run = samples.slice(start, i);
  const runGaps = [];
  for (let j = 1; j < run.length; j++) runGaps.push(run[j].at - run[j - 1].at);
  console.log(
    `  ${new Date(run[0].at).toISOString()}  n=${run.length}  cadence p50=${runGaps.length ? p(runGaps, 0.5) : "-"}`,
  );
  start = i;
}

