import { readFileSync } from "node:fs";

const path = process.argv[2];
const raw = JSON.parse(readFileSync(path, "utf8"));
const samples = raw.result
  .map((s) => (typeof s === "string" ? JSON.parse(s) : s))
  .sort((a, b) => a.at - b.at);

const p = (arr, q) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.floor(q * s.length))];
};
const tally = (arr, f) => {
  const o = {};
  for (const x of arr) o[f(x)] = (o[f(x)] ?? 0) + 1;
  return o;
};

function report(label, run) {
  const gaps = [];
  for (let i = 1; i < run.length; i++) {
    const g = run[i].at - run[i - 1].at;
    if (g <= 60_000) gaps.push(g);
  }
  const ms = run.map((s) => s.ms);
  const up = run.map((s) => s.upstreamMs);
  const mb = tally(run, (s) => s.musicBrainzCalls);
  const oneShare = ((mb[1] ?? 0) / run.length) * 100;
  console.log(`\n=== ${label}  (n=${run.length}) ===`);
  console.log(`  started      ${new Date(run[0].at).toISOString()}`);
  console.log(
    `  cadence      p50=${p(gaps, 0.5)}  p90=${p(gaps, 0.9)}  mean=${Math.round(gaps.reduce((a, b) => a + b, 0) / (gaps.length || 1))}`,
  );
  console.log(`  duration     p50=${p(ms, 0.5)}  p90=${p(ms, 0.9)}`);
  console.log(`  upstream     p50=${p(up, 0.5)}  p90=${p(up, 0.9)}`);
  console.log(`  mbCalls      ${JSON.stringify(mb)}  (1-call share ${oneShare.toFixed(0)}%)`);
  console.log(`  outcome      ${JSON.stringify(tally(run, (s) => s.outcome))}`);
  const floor = ((mb[1] ?? 0) * 1100 + (mb[2] ?? 0) * 2200) / run.length;
  console.log(`  lock floor   ${Math.round(floor)} ms/artist`);
}

report("ALL SAMPLES", samples);

let start = 0;
for (let i = 1; i <= samples.length; i++) {
  if (i !== samples.length && samples[i].at - samples[i - 1].at <= 60_000)
    continue;
  report(`RUN starting ${new Date(samples[start].at).toISOString()}`, samples.slice(start, i));
  start = i;
}

