1	const RATE_LIMITED_DEFAULT = "5";
2	
3	// Non-success Spotify response -> the Error we throw. Returns null for 2xx.
4	// `overrides` adds endpoint-specific status codes (e.g. player controls' 403/404).
5	function spotifyError(response, overrides = {}) {
6	  const byStatus = {
7	    401: () => new Error("TOKEN_EXPIRED"),
8	    429: () =>
9	      new Error(
10	        `RATE_LIMITED:${response.headers.get("Retry-After") ?? RATE_LIMITED_DEFAULT}`,
11	      ),
12	    ...overrides,
13	  };
14	  if (byStatus[response.status]) return byStatus[response.status]();
15	  return response.ok ? null : new Error(`SPOTIFY_ERROR:${response.status}`);
16	}
17	
18	export async function fetchCurrentlyPlaying(token) {
19	  const response = await fetch(
20	    "https://api.spotify.com/v1/me/player/currently-playing",
21	    {
22	      headers: { Authorization: `Bearer ${token}` },
23	    },
24	  );
25	
26	  if (response.status === 204) return null;
27	  const err = spotifyError(response);
28	  if (err) throw err;
29	
30	  const data = await response.json();
31	  if (!data.item) return null;
32	
33	  return {
34	    trackName: data.item.name,
35	    artistName: data.item.artists[0]?.name ?? null, // PRIMARY artist — keep, used elsewhere for geo lookup
36	    artistNames: data.item.artists.map((a) => a.name).join(", ") || null, // all artists joined, for display
37	    albumImageUrl: data.item.album.images[0]?.url ?? null,
38	    trackId: data.item.id,
39	    isPlaying: data.is_playing,
40	    progressMs: data.progress_ms,
41	    durationMs: data.item.duration_ms,
42	  };
43	}
44	
45	async function playerCommand(method, command, token, body, deviceId) {
46	  const query = deviceId ? `?device_id=${encodeURIComponent(deviceId)}` : "";
47	  const response = await fetch(
48	    `https://api.spotify.com/v1/me/player/${command}${query}`,
49	    {
50	      method,
51	      headers: {
52	        Authorization: `Bearer ${token}`,
53	        ...(body ? { "Content-Type": "application/json" } : {}),
54	      },
55	      ...(body ? { body: JSON.stringify(body) } : {}),
56	    },
57	  );
58	  if (response.status === 204) return; // success (no body)
59	  const err = spotifyError(response, {
60	    403: () => new Error("PLAYBACK_UNAVAILABLE"), // non-Premium / restricted
61	    404: () => new Error("NO_ACTIVE_DEVICE"),
62	  });
63	  if (err) throw err;
64	}
65	
66	/**
67	 * Spotify Connect devices the account can currently reach.
68	 *
69	 * Needs the `user-read-playback-state` scope (see OAUTH_SCOPE in
70	 * server/auth.js). A session minted before that scope was added keeps working
71	 * for everything else, so a 403 here means "stale consent", NOT "no Premium"
72	 * — hence its own error rather than playerCommand's PLAYBACK_UNAVAILABLE.
73	 */
74	export async function fetchDevices(token) {
75	  const response = await fetch("https://api.spotify.com/v1/me/player/devices", {
76	    headers: { Authorization: `Bearer ${token}` },
77	  });
78	  const err = spotifyError(response, {
79	    403: () => new Error("INSUFFICIENT_SCOPE"),
80	  });
81	  if (err) throw err;
82	  const data = await response.json();
83	  return data.devices ?? [];
84	}
85	
86	// `is_restricted` devices accept no Web API commands at all, so targeting one
87	// would swap a 404 for a silent no-op. An already-active device is preferred
88	// when present; otherwise any open client will do — that's the whole point,
89	// since Spotify only refuses the bare call because *none* is active.
90	function pickPlaybackDevice(devices) {
91	  const usable = devices.filter((d) => !d.is_restricted && d.id);
92	  return usable.find((d) => d.is_active) ?? usable[0] ?? null;
93	}
94	
95	/**
96	 * Start playback, recovering from Spotify's "no active device" refusal.
97	 *
98	 * `PUT /me/player/play` 404s when nothing is currently playing — the common
99	 * case on a fresh login, where the user has Spotify open somewhere but hasn't
100	 * pressed play. Rather than surfacing that as an error, look for a reachable
101	 * device and aim at it explicitly.
102	 *
103	 * Only `play` gets this treatment: pause/next against no device are genuinely
104	 * meaningless, and waking a client to immediately pause it would be surprising.
105	 */
106	export async function play(token, { contextUri, deviceId } = {}) {
107	  const body = contextUri ? { context_uri: contextUri } : undefined;
108	  try {
109	    return await playerCommand("PUT", "play", token, body, deviceId);
110	  } catch (err) {
111	    // An explicit deviceId that 404s is a dead device, not a missing one —
112	    // re-resolving would just pick the same list and loop.
113	    if (err.message !== "NO_ACTIVE_DEVICE" || deviceId) throw err;
114	
115	    const device = pickPlaybackDevice(await fetchDevices(token));
116	    // Nothing open anywhere. No API call can fix this; the user has to open
117	    // Spotify, so let NO_ACTIVE_DEVICE through with its original meaning.
118	    if (!device) throw err;
119	    return playerCommand("PUT", "play", token, body, device.id);
120	  }
121	}
122	export const pause = (token) => playerCommand("PUT", "pause", token);
123	export const skipToNext = (token) => playerCommand("POST", "next", token);
124	
125	export async function fetchFollowedArtists(token) {
126	  const artists = [];
127	  let after;
128	  do {
129	    const url = new URL("https://api.spotify.com/v1/me/following");
130	    url.searchParams.set("type", "artist");
131	    url.searchParams.set("limit", "50");
132	    if (after) url.searchParams.set("after", after);
133	    const response = await fetch(url, {
134	      headers: { Authorization: `Bearer ${token}` },
135	    });
136	    const err = spotifyError(response);
137	    if (err) throw err;
138	    const data = await response.json();
139	    for (const a of data.artists.items) {
140	      artists.push({
141	        id: a.id,
142	        name: a.name,
143	        imageUrl: a.images[0]?.url ?? null,
144	      });
145	    }
146	    after = data.artists.cursors.after ?? null;
147	  } while (after);
148	  return artists;
149	}

